SELECT id, store_id, staff_name, phone, employment_status, service_enabled,
       version, created_at, updated_at
FROM merchant_staff
WHERE merchant_id = #{merchantId}

ORDER BY id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT id, store_id, member_name, phone, status, invited_by, created_at, updated_at
FROM merchant_member_invitation
WHERE merchant_id = #{merchantId}

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM merchant_member_invitation
WHERE merchant_id = #{merchantId}
